    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marks = {v for v in counts if v != bg}
    if not marks:
        return [row[:] for row in grid]
    mark = next(iter(marks))
    out = [row[:] for row in grid]

    rowpos = {r: [c for c in range(w) if grid[r][c] == mark] for r in range(h)}
    colpos = {c: [r for r in range(h) if grid[r][c] == mark] for c in range(w)}

    # Find the four strongly marked lines forming the frame.
    best = None
    for top in range(h):
        if len(rowpos[top]) < 2:
            continue
        for bottom in range(top + 1, h):
            if len(rowpos[bottom]) < 2:
                continue
            for left in range(w):
                if len(colpos[left]) < 2:
                    continue
                for right in range(left + 1, w):
                    if len(colpos[right]) < 2:
                        continue
                    corners = sum(
                        grid[r][c] == mark
                        for r, c in ((top, left), (top, right),
                                     (bottom, left), (bottom, right))
                    )
                    # Permit a one-cell offset at a corner, as in imperfect frames.
                    near = sum(
                        any(abs(c - x) <= 1 for x in rowpos[r])
                        for r, c in ((top, left), (top, right),
                                     (bottom, left), (bottom, right))
                    )
                    near += sum(
                        any(abs(r - y) <= 1 for y in colpos[c])
                        for r, c in ((top, left), (top, right),
                                     (bottom, left), (bottom, right))
                    )
                    support = min(len(rowpos[top]), len(rowpos[bottom]),
                                  len(colpos[left]), len(colpos[right]))
                    score = (corners, near, support,
                             len(rowpos[top]) + len(rowpos[bottom]) +
                             len(colpos[left]) + len(colpos[right]),
                             (bottom - top) * (right - left))
                    if best is None or score > best[0]:
                        best = (score, top, bottom, left, right)

    if best is None:
        return out

    _, top, bottom, left, right = best

    def fill_row(r):
        p = rowpos[r]
        if len(p) >= 2:
            for c in range(min(p), max(p) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    def fill_col(c):
        p = colpos[c]
        if len(p) >= 2:
            for r in range(min(p), max(p) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    fill_row(top)
    fill_row(bottom)
    fill_col(left)
    fill_col(right)
